/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var isArray = require( '@stdlib/assert/is-array' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getField = require( './field/get.js' );
var setField = require( './field/set.js' );

var getOrder = require( './order/get.js' );
var setOrder = require( './order/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:compare:main' );


// MAIN //

/**
* Compare constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {(string|Array<string>)} [field] - data fields to sort
* @param {(string|Array<string>)} [options.order=['ascending']] - desired sort order for each field
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Compare} compare instance
*
* @example
* var compare = new Compare({
*     'field': 'amount'
* });
* // returns <Compare>
*/
function Compare( options ) {
	var nfields;
	var nargs;
	var order;
	var opts;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Compare ) ) {
		if ( nargs ) {
			return new Compare( options );
		}
		return new Compare();
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'field' ) ) {
		throw new TypeError( 'invalid argument. Options argument must contain a field property.' );
	}

	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Determine the number of fields:
	if ( isArray( options.field ) ) {
		nfields = options.field.length;
	} else if ( isString( options.field ) ) {
		nfields = 1;
	} else {
		nfields = 0;
	}

	// Resolve the order array, padding with defaults as needed...
	if ( hasProp( options, 'order' ) ) {
		if ( isArray( options.order ) ) {
			order = options.order.slice();
		} else if ( isString( options.order ) ) {
			order = [ options.order ];
		} else {
			order = [];
		}
	} else {
		order = [];
	}

	// Pad the order array with default values if there are fewer order entries than field entries:
	for ( i = order.length; i < nfields; i++ ) {
		order.push( opts.order[ 0 ] );
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( k === 'order' ) {
			v = order;
		} else if ( hasProp( options, k ) ) {
			v = options[ k ];
		} else {
			continue;
		}
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Compare, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Compare
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Compare, 'name', 'Compare' );

/**
* Data fields to sort.
*
* @name field
* @memberof Compare.prototype
* @type {(string|Array<string>)}
*
* @example
* var compare = new Compare({
*     'field': 'amount'
* });
*
* var v = compare.field;
* // returns [ 'amount' ]
*/
setReadWriteAccessor( Compare.prototype, 'field', getField, setField );

/**
* Desired sort order for each field.
*
* @name order
* @memberof Compare.prototype
* @type {(string|Array<string>|void)}
* @default [ 'ascending' ]
*
* @example
* var compare = new Compare({
*     'field': 'amount',
*     'order': 'descending'
* });
*
* var v = compare.order;
* // returns [ 'descending' ]
*/
setReadWriteAccessor( Compare.prototype, 'order', getOrder, setOrder );

/**
* Compare properties.
*
* @name properties
* @memberof Compare.prototype
* @type {Array<string>}
*
* @example
* var compare = new Compare({
*     'field': 'amount'
* });
*
* var v = compare.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Compare.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Compare.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var compare = new Compare({
*     'field': 'amount'
* });
*
* var v = compare.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Compare.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Compare;
